export const CHUNK_SIZE=16;
const localIndex=(x,y,z)=>x+16*(z+16*y),smooth=t=>t*t*(3-2*t);
export function smoothNoise(x,z,seed,scale){const ax=Math.floor(x/scale),az=Math.floor(z/scale),u=smooth(x/scale-ax),v=smooth(z/scale-az);return (noise(ax,az,seed)*(1-u)+noise(ax+1,az,seed)*u)*(1-v)+(noise(ax,az+1,seed)*(1-u)+noise(ax+1,az+1,seed)*u)*v;}
const bounds={village:[4,0,4,23,22,22],desert_temple:[38,0,3,53,26,18],jungle_temple:[5,0,41,16,26,51],witch_hut:[45,0,45,52,27,52],stronghold:[40,2,22,55,8,35],dungeon:[25,2,10,33,8,18],mineshaft:[4,3,27,33,7,32],ocean_monument:[22,0,40,40,16,61],desert_well:[55,0,15,60,27,20],nether_fortress:[18,10,7,49,18,46]};
export class ChunkWorld{
 constructor(seed,dimension='overworld',flat=false,generator=4,saved={}){this.seed=String(seed);this.dimension=dimension;this.flat=flat;this.generator=generator;this.s=hashSeed(this.seed+dimension);this.chunks=new Map();this.regions=new Map();this.edits=new Map(sanitizeEdits(saved.edits||[]));this.core=generateDimension(seed,dimension,flat,Math.min(generator,3));this.structures=generator<4||dimension==='end'?[...this.core.structures]:[];this.chests=generator<4||dimension==='end'?{...this.core.chests}:{};this.spawns=generator<4||dimension==='end'?this.core.spawns:[];this.spawn=generator<4||dimension==='end'?this.core.spawn:this.safeSpawn();this.limit=400;}
 height(x,z){if(this.flat)return 6;return Math.max(4,Math.min(28,Math.floor(7+smoothNoise(x,z,this.s,96)*15+smoothNoise(x,z,this.s+9,24)*6)));}
 biome(x,z){if(this.height(x,z)<11)return 'ocean';const n=smoothNoise(x,z,this.s+701,140);return n>.64?'desert':n<.34?'forest':'plains';}
 safeSpawn(){if(this.dimension==='nether')return this.core.spawn;return [32.5,this.height(32,32)+2.62,32.5];}
 editKey(x,y,z){return this.generator<4&&x>=0&&z>=0&&x<SIZE&&z<SIZE?index(x,y,z):`${x},${y},${z}`;}
 get(x,y,z){if(!worldValid(x,y,z))return 0;const key=this.editKey(x,y,z);if(this.edits.has(key))return this.edits.get(key);const cx=Math.floor(x/16),cz=Math.floor(z/16),chunk=this.chunk(cx,cz);return chunk[localIndex(x-cx*16,y,z-cz*16)];}
 set(x,y,z,b){if(!worldValid(x,y,z)||y===0||!Number.isInteger(b)||!BLOCKS[b])return;this.edits.set(this.editKey(x,y,z),b);}
 terrain(x,y,z,height,zone){if(this.dimension==='end'){if(x>=0&&z>=0&&x<64&&z<64)return this.core.blocks[index(x,y,z)];return 0;}if(this.generator<4&&x>=0&&z>=0&&x<64&&z<64)return this.core.blocks[index(x,y,z)];if(this.dimension==='nether'){// Preserve the safe return portal/platform in all generator versions.
 if(x>=6&&x<=12&&z>=6&&z<=12&&y>=10&&y<=16)return this.core.blocks[index(x,y,z)];if(y===0||y===HEIGHT-1)return 20;if(y>=36)return 36;const h=5+Math.floor(smoothNoise(x,z,this.s,18)*5);if(y<=h)return noise(x,y*977+z,this.s)>.985?53:36;return y<=7?44:0;}
 const h=height??this.height(x,z),biome=zone??this.biome(x,z);if(y===0)return 20;if(y>h)return y<=10?21:0;if(y===h)return biome==='desert'||h<11?8:1;if(y>h-3)return biome==='desert'?8:2;const n=noise(x,y*977+z,this.s+73);if(n>.98)return y<5?30:y<8?29:y<12?28:27;if(n<.007&&y<8)return 31;return 3;}
 region(rx,rz){const key=rx+','+rz;if(this.regions.has(key))return this.regions.get(key);const candidates=[];if(this.dimension!=='end'&&!this.flat){const n=noise(rx,rz,this.s+481),x=rx*192+24+Math.floor(noise(rx,rz,this.s+3)*120),z=rz*192+24+Math.floor(noise(rx,rz,this.s+4)*120),biome=this.biome(x,z);let type=this.dimension==='nether'?(n>.25?'nether_fortress':null):n<.18?'mineshaft':n<.27?'dungeon':n<.33?'stronghold':biome==='desert'?(n<.72?'desert_temple':'desert_well'):biome==='ocean'?(n>.65?'ocean_monument':null):biome==='forest'?(n<.65?'jungle_temple':'witch_hut'):(n>.55?'village':null);if(type){const underground=['mineshaft','dungeon','stronghold'].includes(type),baseY=underground?3:type==='nether_fortress'?12:type==='ocean_monument'?5:this.height(x,z)+1;let slope=0;for(const [dx,dz]of [[-12,-12],[12,12],[-12,12],[12,-12]])slope=Math.max(slope,Math.abs(this.height(x+dx,z+dz)-this.height(x,z)));if(underground||this.dimension==='nether'||type==='ocean_monument'||slope<=5)candidates.push({type,name:STRUCTURE_NAMES[type],pos:[x,baseY,z],id:key+':'+type});}}
 this.regions.set(key,candidates);if(this.regions.size>300)this.regions.delete(this.regions.keys().next().value);return candidates;}
 nearbyStructures(cx,cz){if(this.generator<4)return [];const out=[],rx=Math.floor(cx*16/192),rz=Math.floor(cz*16/192);for(let dx=-1;dx<=1;dx++)for(let dz=-1;dz<=1;dz++)out.push(...this.region(rx+dx,rz+dz));return out;}
 chunk(cx,cz){const key=cx+','+cz;if(this.chunks.has(key)){const a=this.chunks.get(key);this.chunks.delete(key);this.chunks.set(key,a);return a;}const a=new Uint16Array(16*16*HEIGHT),put=(x,y,z,b)=>{if(x>=cx*16&&x<cx*16+16&&z>=cz*16&&z<cz*16+16&&y>=0&&y<HEIGHT)a[localIndex(x-cx*16,y,z-cz*16)]=b;};for(let x=cx*16;x<cx*16+16;x++)for(let z=cz*16;z<cz*16+16;z++){const h=this.height(x,z),biome=this.biome(x,z);for(let y=0;y<HEIGHT;y++)put(x,y,z,this.terrain(x,y,z,h,biome));}
 // Trees are selected by absolute coordinates, so branches crossing chunks never depend on load order.
 if(this.dimension==='overworld'&&!this.flat)for(let x=cx*16-2;x<cx*16+18;x++)for(let z=cz*16-2;z<cz*16+18;z++){if(this.generator<4&&x>=0&&z>=0&&x<64&&z<64)continue;const h=this.height(x,z);if(this.biome(x,z)==='desert'||h<11||noise(x,z,this.s+88)<.992)continue;for(let dx=-2;dx<=2;dx++)for(let dz=-2;dz<=2;dz++)for(let y=h+3;y<h+6;y++)if(Math.abs(dx)+Math.abs(dz)<4)put(x+dx,y,z+dz,7);for(let y=h+1;y<h+5;y++)put(x,y,z,6);}
 for(const st of this.nearbyStructures(cx,cz)){const box=bounds[st.type];if(!box)continue;const source=this.template(st.type),[x0,y0,z0,x1,y1,z1]=box,anchor=source.structures.find(s=>s.type===st.type).pos,ox=st.pos[0]-anchor[0],oz=st.pos[2]-anchor[2],oy=st.pos[1]-anchor[1];if(x1+ox<cx*16||x0+ox>=cx*16+16||z1+oz<cz*16||z0+oz>=cz*16+16)continue;
 for(let x=x0;x<x1;x++)for(let z=z0;z<z1;z++){const underground=['dungeon','stronghold','mineshaft'].includes(st.type),base=st.pos[1];if(!underground&&st.type!=='nether_fortress'&&st.type!=='ocean_monument'){for(let y=1;y<base;y++)put(x+ox,y,z+oz,st.type.startsWith('desert')?35:2);for(let y=base;y<HEIGHT;y++)put(x+ox,y,z+oz,0);}for(let y=underground||st.type==='ocean_monument'?y0:Math.max(y0,anchor[1]-1);y<y1;y++){if(y+oy<1)continue;put(x+ox,y+oy,z+oz,source.blocks[index(x,y,z)]);}}
 for(const [k,slots]of Object.entries(source.chests)){const [x,y,z]=k.split(',').map(Number);if(x>=x0&&x<x1&&z>=z0&&z<z1){const target=[x+ox,y+oy,z+oz].join(',');this.chests[target]??=structuredClone(slots);}}if(!this.structures.some(s=>s.id===st.id))this.structures.push(st);
 }
 this.chunks.set(key,a);while(this.chunks.size>this.limit)this.chunks.delete(this.chunks.keys().next().value);return a;}
 template(type){this.templates??={};const dim=type==='nether_fortress'?'nether':'overworld';return this.templates[dim]??=generateDimension('structure-template',dim,false,3);}
 serialize(){return [...this.edits];}
}
